def P(t, s='BodyX'): return Paragraph(t, styles[s])
def bullets(items): return [P('• '+x, 'BulletX') for x in items]
def table(rows, widths, header=True):
    data=[[P(str(c), 'SmallX') for c in r] for r in rows]
    ts=[('VALIGN',(0,0),(-1,-1),'TOP'),('GRID',(0,0),(-1,-1),.35,colors.HexColor('#CBD5E1')),('LEFTPADDING',(0,0),(-1,-1),6),('RIGHTPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5)]
    if header: ts += [('BACKGROUND',(0,0),(-1,0),NAVY),('TEXTCOLOR',(0,0),(-1,0),colors.white)]
    for i in range(1,len(rows)):
        if i%2==0: ts.append(('BACKGROUND',(0,i),(-1,i),colors.HexColor('#F8FAFC')))
    return Table(data,colWidths=widths,repeatRows=1 if header else 0,style=TableStyle(ts),hAlign='LEFT')

def header_footer(canvas, doc):
    canvas.saveState(); w,h=A4
    if doc.page>1:
        canvas.setStrokeColor(colors.HexColor('#D8E0EB')); canvas.line(18*mm, 15*mm, w-18*mm, 15*mm)
        canvas.setFont('Helvetica',7.5); canvas.setFillColor(MUTED)
        canvas.drawString(18*mm,10*mm,'SOAR Project Documentation | Security Engineering Review')
        canvas.drawRightString(w-18*mm,10*mm,f'Page {doc.page}')
    canvas.restoreState()

